SELECT m.*, u.user_name FROM ai_chat_message m
LEFT JOIN sys_user u ON u.user_id = m.user_id
WHERE m.user_id = #{userId}
ORDER BY m.id DESC
LIMIT #{limit}

SELECT m.*, u.user_name FROM ai_chat_message m
LEFT JOIN sys_user u ON u.user_id = m.user_id

    AND m.user_id = #{userId}
    AND m.emotion = #{emotion}

ORDER BY m.id DESC
LIMIT 200
